import{_ as t,a as r,b as o}from"./chunks/energy-price.CGaBL0Ht.js";import{_ as a,o as i,c as n,a3 as s}from"./chunks/framework.BlfGB29P.js";const y=JSON.parse('{"title":"Energy – Widgets","description":"Energy flow, consumption, battery and prices as a separate Home Assistant widget set.","frontmatter":{"title":"Energy – Widgets","description":"Energy flow, consumption, battery and prices as a separate Home Assistant widget set."},"headers":[],"relativePath":"en/projects/grafik-visual-studio/energy.md","filePath":"en/projects/grafik-visual-studio/energy.md","lastUpdated":1793113714000}'),d={name:"en/projects/grafik-visual-studio/energy.md"};function c(l,e,g,u,h,p){return i(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="energy-–-widgets" tabindex="-1">Energy – Widgets <a class="header-anchor" href="#energy-–-widgets" aria-label="Permalink to &quot;Energy – Widgets&quot;">​</a></h1><p><strong>Energy 0.1.0</strong> is a separate external set for <strong>Grafik Visual Studio 0.1.255 or newer</strong>, independent of Industrial. Entity selection and live readings work in editor and runtime. Period selection changes the runtime dashboard locally without writing Home Assistant states.</p><h2 id="original-project-and-attribution" tabindex="-1">Original project and attribution <a class="header-anchor" href="#original-project-and-attribution" aria-label="Permalink to &quot;Original project and attribution&quot;">​</a></h2><p>The reference is <a href="https://github.com/ioBroker/ioBroker.vis-2-widgets-energy" target="_blank" rel="noreferrer">ioBroker.vis-2-widgets-energy</a> by <strong>bluefox / GermanBluefox and contributors</strong>, licensed under <strong>MIT</strong>. See the <a href="https://github.com/ioBroker/ioBroker.vis-2-widgets-energy/tree/main/docs/en" target="_blank" rel="noreferrer">original documentation</a> for the ioBroker version. Inspected revision: <a href="https://github.com/ioBroker/ioBroker.vis-2-widgets-energy/commit/d0a53871ea7e57c5100de2a1f2ef7b2ee82059c7" target="_blank" rel="noreferrer">d0a53871</a>, October 7, 2026.</p><p>Energy is an <strong>independent Home Assistant adaptation by rockbaer2007</strong>, not an unchanged port or an official ioBroker release. Rendering, icons and HA integration are newly implemented; original React/vis-2 code and images are not embedded. The package also includes attribution and license information.</p><h2 id="images" tabindex="-1">Images <a class="header-anchor" href="#images" aria-label="Permalink to &quot;Images&quot;">​</a></h2><p>These runtime images use <strong>test data</strong>, not live measurements.</p><p><img src="'+t+'" alt="Energy distribution between grid, house, PV, battery and wallbox"></p><table tabindex="0"><thead><tr><th>Battery</th><th>Dynamic electricity price</th></tr></thead><tbody><tr><td><img src="'+r+'" alt="Battery charge, power and remaining time"></td><td><img src="'+o+'" alt="Hourly prices with cheap and expensive hours highlighted"></td></tr></tbody></table><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><ol><li>Update Studio to <strong>0.1.255 or newer</strong>, then reload with <strong>Ctrl+F5</strong>.</li><li><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/raw/master/ha_grafik_visual_studio/packages/energy/ugso.energy.wg" target="_blank" rel="noreferrer">Download ugso.energy.wg</a>.</li><li>Install through <strong>Settings → Widget packages → Local</strong>. <strong>Energy</strong> appears in the palette.</li><li>Insert a widget and use <strong>…</strong> to select its Home Assistant entities.</li></ol><p>The package contains eight declarative widgets, original SVG palette icons and license/instructions, without executable package code. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/ha_grafik_visual_studio/packages/energy" target="_blank" rel="noreferrer">Source and package instructions</a>.</p><h2 id="the-eight-widgets" tabindex="-1">The eight widgets <a class="header-anchor" href="#the-eight-widgets" aria-label="Permalink to &quot;The eight widgets&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Widget</th><th>Features and sources</th></tr></thead><tbody><tr><td>Energy distribution</td><td>House and grid plus <strong>1–10 additional nodes</strong>. Each has a name, color, power entity, factor, reversible flow and optional second reading/unit. Animation can be disabled.</td></tr><tr><td>Energy consumption</td><td>Up to <strong>six Recorder series</strong>, bar or line chart, counter differences or sums of individual consumption amounts; hourly/daily/monthly buckets by period.</td></tr><tr><td>Consumption comparison</td><td>Live values from up to <strong>six devices</strong>, bar/line/pie, sorting, per-series color and unit. Mixed units are not combined on one axis.</td></tr><tr><td>Period selector</td><td>Day/week/month/year, date and Previous/Today/Next. One selector can control multiple history widgets on the same page.</td></tr><tr><td>Self-sufficiency and self-consumption</td><td>Two rings from production, grid import/export and optional house consumption. Without a house entity it is calculated from the balance.</td></tr><tr><td>Battery storage</td><td>Charge, power, capacity, stored energy and estimated time to full/empty. Configurable charging sign and W/kW power.</td></tr><tr><td>Energy costs</td><td>Consumption × purchase price + base fee per calendar day − export revenue; live energy counters or Recorder period. Configurable currency.</td></tr><tr><td>Dynamic electricity price</td><td>JSON state or attribute, hourly bars, current/cheap/expensive hours and average. Negative prices are preserved.</td></tr></tbody></table><h2 id="units-and-unknown-values" tabindex="-1">Units and unknown values <a class="header-anchor" href="#units-and-unknown-values" aria-label="Permalink to &quot;Units and unknown values&quot;">​</a></h2><p>Set <strong>factors explicitly</strong>, e.g. <code>0.001</code> for Wh → kWh or W → kW. Power is not automatically integrated into energy. Self-sufficiency requires matching quantities and units: either power or energy from the same period.</p><p>Positive grid values mean import, negative values export. A configured separate export source replaces the negative grid component. Positive distribution node values flow toward the house by default; enable <strong>reverse flow</strong> for consumers or batteries using the opposite sign convention.</p><p>Missing or invalid sources show <strong>—</strong>, without fabricated preview measurements. Zero denominators produce unknown ratios. Remaining battery time is an estimate from current power and capacity, not a prediction of future operation.</p><h2 id="recorder-and-period-selection" tabindex="-1">Recorder and period selection <a class="header-anchor" href="#recorder-and-period-selection" aria-label="Permalink to &quot;Recorder and period selection&quot;">​</a></h2><p>History and historical costs require numeric entities retained by the <strong>Home Assistant Recorder</strong>. Enter the selector widget ID from the same page in <strong>period selector ID</strong>, e.g. <code>widget-3</code>. Without a linked selector, the widget uses its own period/date. Empty date means today.</p><p><strong>counter</strong> calculates differences from held Recorder states. Unknown states or counter resets create gaps; resets are not counted as consumption. <strong>sum</strong> adds individual consumption amounts and must not be used with cumulative counters. Current periods include only recorded data; future buckets stay unknown. Total costs require valid complete data in the already recorded part.</p><p>Limits: <strong>366 days</strong>, <strong>six entities</strong>, <strong>20,000 states per series</strong>. Excessive responses are rejected with a notice rather than silently truncated. Calendar boundaries use the local browser time zone. Older periods may be unavailable due to Recorder retention. This version has <strong>no HA long-term statistics</strong>, ioBroker history instances or automatic power integration. Base fees cover the selected calendar period; live counters must match that period.</p><h2 id="price-data" tabindex="-1">Price data <a class="header-anchor" href="#price-data" aria-label="Permalink to &quot;Price data&quot;">​</a></h2><p>Arrays can come from a state or selected attribute, optionally wrapped in <code>prices</code>, <code>today</code>, <code>data</code>, <code>values</code> or <code>result</code>. Automatic time fields: <code>startsAt</code>, <code>start_timestamp</code>, <code>start</code>, <code>date</code>, <code>x</code>; price fields: <code>total</code>, <code>marketprice</code>, <code>price</code>, <code>value</code>, <code>y</code>. Custom field names are supported. Times may be ISO, seconds or milliseconds. A numeric array represents hours starting at local midnight today.</p><p>Use factor <strong>100</strong> for EUR/kWh → ct/kWh or <strong>0.1</strong> for EUR/MWh → ct/kWh. Future-only mode, hour count, cheap/expensive hour counts and highlight colors are configurable.</p><h2 id="differences-from-the-original" tabindex="-1">Differences from the original <a class="header-anchor" href="#differences-from-the-original" aria-label="Permalink to &quot;Differences from the original&quot;">​</a></h2><p>The eight widget categories follow the original concept, with settings and data integration adapted to Studio and Home Assistant. This first version uses local period selection and Recorder states rather than ioBroker OIDs/history. It does not reproduce all vis-2 layout/chart options or provide direct device writes.</p>',27)])])}const b=a(d,[["render",c]]);export{y as __pageData,b as default};
